function [status] = PlotHarmonicFitErrors(beta_all_orth,error_all_orth,beta_all_opt,error_all_opt,grain_volumes)
%  Program for plotting the errors in stress associated with a harmonic expansion 
%
%    Input:   (1) files with the weights generated by
%                   FitFieldDataWithHarmonics script
%
%    Output: (1) plots of the expansion errors grain-by-grain
%
   ifigure=10;
   ab_label = 'Grain Number';
   ord_label = 'Expansion Error';
    
     [nframes,ncomps,nmodes,ngrns] = size(beta_all_orth);

     grainerror = zeros(ngrns,1);

     for igrn = 1:1:ngrns
         grainnum(igrn) = igrn;
     end

     % create plot for orthogonality method

   plot_title = ['Grain-by-Grain Error in Stress Expansion for Orthogonality Method'];
   ifigure=ifigure+1;
   figure(ifigure);
   
   clf;
    hold 'on';
  
    for iframe =1:1:nframes

        grainerror(:) = error_all_orth(iframe,:); 
        emax = max(grainerror);
        p = plot(grainnum,grainerror,'b*');

        set(gca,'Box','on','LineWidth',2,'FontName','Helvetica','FontSize',14);
        set(p,'LineWidth',2)


    end
        

axis([0 ngrns 0 emax]);
xlabel(ab_label); 
ylabel(ord_label);   
title(plot_title); 

    hold 'off';

% 
%      % create plot for optimization method
% 
   plot_title = ['Grain-by-Grain Error in Stress Expansion for Optimization Method'];
   ifigure=ifigure+1;
   figure(ifigure);
   clf;    

    hold 'on';
  
    for i =1:1:nframes


        grainerror(:) = error_all_opt(iframe,:); 
        emax = max(grainerror);
        p = plot(grainnum,grainerror,'b*');

        set(gca,'Box','on','LineWidth',2,'FontName','Helvetica','FontSize',14);
        set(p,'LineWidth',2)


    end

 


axis([0 ngrns 0 emax]);
xlabel(ab_label); 
ylabel(ord_label);   
title(plot_title); 
 

    hold 'off';   


     % create plot for orthogonality method

   plot_title = 'Stress Expansion Error Grain Volume Dependence';
   ab_label = 'Grain Volume';
   ord_label = 'Expansion Error';


   ifigure=ifigure+1;
   figure(ifigure);
      clf;

    hold 'on';
  
    for iframe =1:1:nframes

        grainerror(:) = error_all_orth(iframe,:); 
        emax = max(grainerror);
        vmin = min(grain_volumes);
        vmax = max(grain_volumes);
        p = plot(grain_volumes,grainerror,'b*');

        set(gca,'Box','on','LineWidth',2,'FontName','Helvetica','FontSize',14);
        set(p,'LineWidth',2)


    end
        

axis([vmin vmax 0 emax]);
xlabel(ab_label); 
ylabel(ord_label);   
title(plot_title); 

    hold 'off';


    status = 'done with plots';
    
    
    
end


    


